  },

  "requirements": {
    "req_1_nonce": {
      "id": "REQ-1",
      "spec_text": "Nonces must be 96-bit (12 bytes) and cryptographically random — not counter-based",
      "verdict": "PASS",
      "evidence": {
        "nonce_py": {
          "file": "crypto_service/nonce.py",
          "finding": "generate_nonce() 使用 os.urandom(12)。无计数器变量、无 struct.pack、无时间戳或 PID。纯 CSPRNG 来源的 96-bit nonce。文档字符串引用了 NIST SP 800-38D §8.3 碰撞界限（2^48 消息，碰撞概率 < 2^-32）。",
          "verdict": "PASS"
        },
        "encryption_py": {
          "file": "crypto_service/encryption.py",
